/** One file of a package version. */
export const StudioPackageFile = z.object({
  /** Its path in the package. */
  "path": z.string(),
  /** Its `resourceType`, for a FHIR artefact. */
  "resourceType": z.string().nullable().optional(),
  /** Its canonical URL. */
  "url": z.string().nullable().optional(),
  /** Its version. */
  "version": z.string().nullable().optional(),
})
export type StudioPackageFile = z.infer<typeof StudioPackageFile>

/** The package list. */
export const StudioPackageList = z.object({
  /** One row per package, by name. */
  "packages": z.array(StudioPackage),
})
export type StudioPackageList = z.infer<typeof StudioPackageList>

/** One package version read from top to bottom. */
export const StudioPackagePage = z.object({
  /** How many approvals its kind needs. */
  "approvalsRequired": integer,
  /** Who has approved it. */
  "approvers": z.array(z.string()),
  /** What changed against the previous published version. */
  "changes": z.array(StudioArtefactChange),
  /** The stored check results. */
  "checks": z.array(StudioCheckResult),
  "commentRefusal": ActionRefusal.nullable().optional(),
  /** Whether the signed-in person may comment in the discussion. */
  "commentable": z.boolean(),
  "editRefusal": ActionRefusal.nullable().optional(),
  /** Whether the signed-in person may change the draft's files and version. */
  "editable": z.boolean(),
  /** Its files, to open in an editor. */
  "files": z.array(StudioPackageFile),
  /** The history, oldest first. */
  "history": z.array(StudioHistoryEntry),
  /** The holder's one change note for the whole draft. */
  "note": z.string().nullable().optional(),
  /** Its row in the list, with the actions. */
  "package": StudioPackage,
  /** Who accepted it at review. */
  "reviewer": z.string().nullable().optional(),
  /** The draft's revision, also its `ETag`: a save sends it back as `If-Match`. */
  "revision": integer,
})
export type StudioPackagePage = z.infer<typeof StudioPackagePage>

/** What a parameter holds, as JSON Schema names it. */
export const StudioParameterType = z.enum(["boolean", "integer", "string"])
export type StudioParameterType = z.infer<typeof StudioParameterType>

/** One parameter's JSON Schema. */
export const StudioParameter = z.object({
  /** For a code: the codes allowed. */
  "enum": z.array(z.string()).nullable().optional(),
  /** For a text: it may not be empty. */
  "minLength": integer.nullable().optional(),
  /** What it holds. */
  "type": StudioParameterType,
})
export type StudioParameter = z.infer<typeof StudioParameter>

/** The JSON Schema of an action's parameters (`ActionDescriptor::parameter_schema`), typed: an object with each parameter as a property, the required ones required, and nothing else. */
export const StudioParameterSchema = z.object({
  /** The JSON Schema dialect. */
  "$schema": z.string(),
  /** Always false: no other parameter is allowed. */
  "additionalProperties": z.boolean(),
  /** Each parameter, by name. */
  "properties": z.record(z.string(), StudioParameter),
  /** The parameters a definition must give. */
  "required": z.array(z.string()),
  /** The action's reference. */
  "title": z.string(),
  /** Always `object`. */
  "type": z.string(),
})
export type StudioParameterSchema = z.infer<typeof StudioParameterSchema>

/** Why a Studio request failed. */
export const StudioProblem = z.object({
  /** What went wrong. */
  "detail": z.string(),
  "refusal": ActionRefusal.nullable().optional(),
})
export type StudioProblem = z.infer<typeof StudioProblem>

/** A paste read: the R5 Questionnaire and its report, or why it was not read. */
export const StudioQuestionnaireImport = z.object({
  /** Whether something could not be converted, so the import must not go on. */
  "blocked": z.boolean(),
  "questionnaire": z.record(z.string(), z.unknown()).nullable().optional(),
  "refusal": StudioImportRefusal.nullable().optional(),
  /** What was converted, and what could not be. */
  "report": z.array(StudioConversionFinding),
})
export type StudioQuestionnaireImport = z.infer<typeof StudioQuestionnaireImport>

/** A pasted Questionnaire to read. */
export const StudioQuestionnaireImportInput = z.object({
  /** The text as pasted. */
  "text": z.string(),
  /** The FHIR version to read it as. */
  "version": StudioFhirVersion,
})
export type StudioQuestionnaireImportInput = z.infer<typeof StudioQuestionnaireImportInput>

/** An open Task. */
export const StudioSandboxTask = z.object({
  /** Its state. */
  "state": z.string(),
  /** `ready` or `in-progress`. */
  "status": z.string(),
})
export type StudioSandboxTask = z.infer<typeof StudioSandboxTask>

/** A pending timer. */
export const StudioSandboxTimer = z.object({
  /** How long until it falls due (ISO 8601). */
  "dueIn": z.string(),
  /** The event it raises. */
  "event": z.string(),
})
export type StudioSandboxTimer = z.infer<typeof StudioSandboxTimer>

/** What held at the start, or after a move. */
export const StudioSandboxStep = z.object({
  /** The events the configuration accepts. */
  "accepts": z.array(z.string()),
  /** The typed actions the move ran, stubbed (recorded, never carried out). */
  "actions": z.array(z.string()),
  /** The active states. */
  "configuration": z.array(z.string()),
  /** How long since the start (ISO 8601). */
  "elapsed": z.string(),
  /** Whether the instance is still running. */
  "running": z.boolean(),
  /** The open Tasks. */
  "tasks": z.array(StudioSandboxTask),
  /** The pending timers, earliest first. */
  "timers": z.array(StudioSandboxTimer),
})
export type StudioSandboxStep = z.infer<typeof StudioSandboxStep>

/** How the run went. */
export const StudioSandbox = z.object({
  /** Every Financial Gate of the definition. */
  "gates": z.array(z.string()),
  /** Every guard of the definition, for the author to answer. */
  "guards": z.array(z.string()),
  /** Why the next move could not be taken, if it could not for another reason. */
  "refused": z.string().nullable().optional(),
  /** The run as the text of a `workflow-scenario` file of the package's `tests/` folder. */
  "scenario": z.string(),
  /** The start, then each move taken. */
  "steps": z.array(StudioSandboxStep),
  /** The guards the next move needs answered: it was not taken. */
  "unanswered": z.array(z.string()),
})
export type StudioSandbox = z.infer<typeof StudioSandbox>

/** One move: an event to send, or a wait. */
export const StudioSandboxMove = z.object({
  /** The event to send. */
  "event": z.string().nullable().optional(),
  /** How long to wait (ISO 8601), firing the timers that fall due. */
  "wait": z.string().nullable().optional(),
})
export type StudioSandboxMove = z.infer<typeof StudioSandboxMove>

/** A sandbox run of a draft definition. */
export const StudioSandboxInput = z.object({
  /** The draft Workflow Definition, as the Studio holds it. */
  "definition": z.object({}),
  /** The outcome of each Financial Gate, by canonical URL: `pass`, `defer` or `block`. An unanswered gate defers. */
  "gates": z.record(z.string(), z.string()).optional(),
  /** The author's answer to each guard, by its expression. */
  "guards": z.record(z.string(), z.boolean()).optional(),
  /** The moves so far, in order. */
  "moves": z.array(StudioSandboxMove).optional(),
  /** The name the run takes as a scenario. */
  "name": z.string().nullable().optional(),
})
export type StudioSandboxInput = z.infer<typeof StudioSandboxInput>

/** The ValueSets of the package version and of the published packages. */
export const StudioValueSets = z.object({
  /** The ValueSets, this package's own first. */
  "valueSets": z.array(StudioValueSet),
})
export type StudioValueSets = z.infer<typeof StudioValueSets>

/** A draft's new version. */
export const StudioVersionInput = z.object({
  /** An exact version, e.g. `2.1.0`. */
  "version": z.string(),
})
export type StudioVersionInput = z.infer<typeof StudioVersionInput>

/** One typed action a definition may execute. */
export const StudioWorkflowAction = z.object({
  /** How it is undone. */
  "compensation": StudioCompensation,
  /** Its id, `<context>/<action>`. */
  "id": z.string(),
  /** Its major version. */
  "major": integer,
  /** The JSON Schema of its parameters, from which the Studio generates their fields. */
  "parameterSchema": StudioParameterSchema,
  /** The permission it needs: the user's on a user-triggered transition, the workflow principal's on a timer, eventless or system step. */
  "permission": z.string(),
  /** How a definition names it: `<id>@<major>`. */
  "reference": z.string(),
})
export type StudioWorkflowAction = z.infer<typeof StudioWorkflowAction>

/** The release's workflow actions. */
export const StudioWorkflowActions = z.object({
  /** The actions, by reference. */
  "actions": z.array(StudioWorkflowAction),
})
export type StudioWorkflowActions = z.infer<typeof StudioWorkflowActions>

